import { D, type DiseaseRow } from '../builders';
import type { Disease } from '../schema';

/*
 * High-frequency disease pages for the encounter reference.  These are
 * deliberately authored as disease-specific rows: the helper only fills
 * structural fields, never clinical facts or translations.
 */
type Seed = Omit<DiseaseRow, 'lay' | 'rel' | 'exam' | 'testExplain' | 'cause' | 'admit' | 'related' | 'dlg' | 'v' | 'note'> & {
  lay?: string;
  rel?: string[];
  exam?: string[];
  testExplain?: string[];
  cause?: string;
  admit?: string[];
  related?: string[];
  dlg?: DiseaseRow['dlg'];
  v?: DiseaseRow['v'];
  note?: string;
};

function disease(seed: Seed): Disease {
  const exam = seed.exam ?? ['全身状態とバイタルサインを確認します。', '症状のある部位を診察します。', '必要な診察を追加します。'];
  const testExplain = seed.testExplain ?? [`${seed.en}の状態と重症度を確認するために、検査を行います。`];
  const admit = seed.admit ?? (seed.sev === 'routine' ? ['外来で経過を見ながら治療します。'] : ['状態を確認するため、入院して治療します。']);
  const related = seed.related ?? [];
  const dlg = seed.dlg ?? [
    ['p', 'この病気は治りますか。', `Can this condition be treated?`],
    ['d', seed.explain, `We will explain the condition and treatment based on your results.`],
    ['p', 'どんなことに気をつければいいですか。', 'What should I be careful about?'],
    ['d', seed.red?.[0] ? `次の症状があれば、すぐに受診してください。${seed.red[0]}。` : '症状の変化があれば、早めにご相談ください。', 'Please seek care promptly if your symptoms change.'],
  ];
  return D({ ...seed, exam, testExplain, admit, related, dlg });
}

